document.documentElement.classList.add('js');
const reduce=window.matchMedia('(prefers-reduced-motion: reduce)');
const items=document.querySelectorAll('.reveal');
if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{for(const e of entries){if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}},{threshold:.08});items.forEach(el=>observer.observe(el))}else{items.forEach(el=>el.classList.add('visible'))}
const layers=[...document.querySelectorAll('[data-parallax]')];let ticking=false;
function move(){if(!reduce.matches){layers.forEach(el=>{const bounds=el.parentElement.getBoundingClientRect();if(bounds.bottom>0&&bounds.top<innerHeight){el.style.transform=`translate3d(0,${-bounds.top*Number(el.dataset.parallax)}px,0)`}})}else layers.forEach(el=>el.style.transform='none');ticking=false}
addEventListener('scroll',()=>{if(!ticking){ticking=true;requestAnimationFrame(move)}},{passive:true});reduce.addEventListener('change',move);move();document.getElementById('year').textContent=new Date().getFullYear();
// Sticky header: pins after leaving the hero, reveals on scroll up, hides on scroll down
const header=document.querySelector('header');let lastY=scrollY;let pinned=false;
function headerState(){const y=scrollY;if(y<=12){header.classList.remove('pinned','show','animate');pinned=false}else if(y>140){if(!pinned){header.classList.add('pinned');header.classList.remove('show');void header.offsetHeight;header.classList.add('animate');pinned=true}if(y<lastY-2)header.classList.add('show');else if(y>lastY+2)header.classList.remove('show')}lastY=y}
addEventListener('scroll',headerState,{passive:true});headerState();
// Count-up (or count-down) stats: data-count target, data-from start, data-dur ms, data-prefix/suffix
const counters=document.querySelectorAll('[data-count]');
if(counters.length&&'IntersectionObserver' in window&&!reduce.matches){const co=new IntersectionObserver(entries=>{for(const e of entries){if(!e.isIntersecting)continue;co.unobserve(e.target);const el=e.target,end=Number(el.dataset.count),from=Number(el.dataset.from||0),dur=Number(el.dataset.dur||1400),pre=el.dataset.prefix||'',suf=el.dataset.suffix||'';let t0;const tick=now=>{t0??=now;const p=Math.min(1,(now-t0)/dur),ease=1-Math.pow(1-p,4),v=Math.round(from+(end-from)*ease);el.textContent=pre+v+suf;if(p<1)requestAnimationFrame(tick)};el.textContent=pre+from+suf;setTimeout(()=>requestAnimationFrame(tick),250)}},{threshold:.5});counters.forEach(el=>co.observe(el))}
// Case cards: cursor spotlight + gentle 3D tilt
const grid=document.querySelector('.case-grid');
if(grid&&matchMedia('(hover:hover) and (pointer:fine)').matches){grid.addEventListener('pointermove',e=>{const card=e.target.closest('.case');if(!card)return;const r=card.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;card.style.setProperty('--mx',(x*100).toFixed(1)+'%');card.style.setProperty('--my',(y*100).toFixed(1)+'%');if(!reduce.matches){card.style.setProperty('--ry',((x-.5)*7).toFixed(2)+'deg');card.style.setProperty('--rx',((.5-y)*7).toFixed(2)+'deg')}});grid.addEventListener('pointerleave',()=>grid.querySelectorAll('.case').forEach(c=>{c.style.setProperty('--rx','0deg');c.style.setProperty('--ry','0deg')}),true);grid.querySelectorAll('.case').forEach(c=>c.addEventListener('pointerleave',()=>{c.style.setProperty('--rx','0deg');c.style.setProperty('--ry','0deg')}))}